__modules["components.inputs"] = function()
local U = require("core.util")

local M = {}

local function pick(options, on_pick, command)
  local o = options[tonumber(command)]
  if o then
    on_pick(o.value)
  end
end

-- Menu commands are option positions: ttt ignores menu entries whose command
-- is empty.
function M.dropdown(h, options, value, on_pick, label)
  local entries = {}
  for i, o in ipairs(options) do
    entries[i] = { label = o.label, command = tostring(i), checked = o.value == value }
  end
  h:dropdown({
    label = (label or U.option_label(options, value)) .. " ▾",
    entries = entries,
    on_menu = U.bind(pick, options, on_pick),
  })
end

return M
end

-- src/components/layout.lua -------------------------------------------------
__modules["components.layout"] = function()
local U = require("core.util")

local M = {}

local function merge(into, opts)
  for k, v in pairs(opts or {}) do
    into[k] = v
  end
  return into
end

function M.frame(p, title, render, opts)
  p:box(merge({ border = true, title = title, render = render }, opts))
end

function M.toolbar(p, render, margin_top)
  p:hstack({ height = 1, gap = 1, margin_top = margin_top == nil and 1 or margin_top, render = render })
end

function M.kv(entries)
  local out = { padding_left = 1, margin_top = 1, muted_keys = true }
  for _, e in ipairs(entries) do
    out[#out + 1] = { key = e[1], value = e[2] or "" }
  end
  return out
end

function M.status(p, text, style)
  p:label({ text = text or "", style = style or "muted", padding_left = 1 })
end

local function error_lines(lines, b)
  for _, line in ipairs(lines) do
    b:label({ text = line, style = "danger", padding_left = 1 })
  end
end

local function wrap(out, line, width)
  while #line > width do
    local cut = line:sub(1, width):find(" [^ ]*$")
    if not cut or cut < width / 2 then
      cut = width
    end
    out[#out + 1] = line:sub(1, cut)
    line = line:sub(cut + 1)
  end
  out[#out + 1] = line
end

-- One label per line, so psql's caret under the error position lines up.
function M.error_box(p, title, text)
  local width = 0
  if p.size then
    width = p:size() - 6
  end
  local lines = {}
  for _, line in ipairs(U.split(U.trim(text), "\n")) do
    if width > 20 then
      wrap(lines, line, width)
    else
      lines[#lines + 1] = line
    end
  end
  M.frame(p, title, U.bind(error_lines, lines), { height = #lines + 3, margin_top = 1 })
end

return M
end

-- src/core/db.lua -----------------------------------------------------------
__modules["core.db"] = function()
local storage = require("ttt.storage")
local U = require("core.util")
local S = require("core.state")
local Psql = require("core.psql")
local SQL = require("core.sql")

local Db = {}

local KINDS = { r = "table", p = "table", f = "table", v = "view", m = "view" }

local function pick_schema()
  for _, name in ipairs(S.schemas) do
    if name == S.schema then
      return
    end
  end
  S.schema = "public"
  for _, name in ipairs(S.schemas) do
    if name == "public" then
      return
    end
  end
  S.schema = S.schemas[1] or "public"
end

local function relations_loaded(gen, err, sets)
  if gen ~= S.relations_gen then
    return
  end
  S.relations_loading = false
  S.relations_err = err
  local list = {}
  for _, r in ipairs(not err and sets[1] and sets[1].rows or {}) do
    list[#list + 1] = { name = r[1], relkind = r[2], kind = KINDS[r[2]] or "table", estimate = tonumber(r[3]) }
  end
  S.relations = list
  S.redraw()
end

function Db.load_relations()
  if S.status ~= "ok" then
    return
  end
  S.relations_gen = S.relations_gen + 1
  S.relations_loading = true
  S.relations_err = nil
  S.redraw()
  Psql.query(SQL.relations(S.schema), U.bind(relations_loaded, S.relations_gen))
end

function Db.set_schema(name)
  if name == S.schema then
    return
  end
  S.schema = name
  S.relations = {}
  storage.set("schema", name)
  Db.load_relations()
end

local function connected(gen, cb, err, sets)
  if gen ~= S.gen then
    return
  end
  if err then
    S.status = "error"
    S.message = err
  else
    local info = sets[1] and sets[1].rows[1] or {}
    S.status = "ok"
    S.message = ""
    S.server = { user = info[1], database = info[2], host = info[3], port = info[4], version = info[5] }
    S.schemas = {}
    for _, r in ipairs(sets[2] and sets[2].rows or {}) do
      S.schemas[#S.schemas + 1] = r[1]
    end
    pick_schema()
    Db.load_relations()
  end
  S.redraw()
  if cb then
    cb(err)
  end
end

function Db.connect(cb)
  S.gen = S.gen + 1
  S.status = "connecting"
  S.message = ""
  S.redraw()
  Psql.query(SQL.CONNECT, U.bind(connected, S.gen, cb))
end

function Db.ensure_connected()
  if S.status == "idle" and S.configured() then
    Db.connect()
  end
end

function Db.refresh()
  if S.status == "ok" then
    Db.load_relations()
  else
    Db.connect()
  end
end

-- What the status line calls the server.
function Db.label()
  local c = S.conn
  local uri = U.trim(c.uri)
  if S.server then
    local host = uri ~= "" and uri:match("@([^/?]+)") or (uri == "" and c.host .. ":" .. c.port) or nil
    if not host then
      host = S.server.host .. (S.server.port ~= "" and ":" .. S.server.port or "")
    end
    return S.server.user .. "@" .. host .. "/" .. S.server.database
  end
  if uri ~= "" then
    local uri = U.trim(c.uri):gsub("://([^:@/]*):[^@]*@", "://%1@")
    return (uri:gsub("password=%S+", "password=…"))
  end
  return c.user .. "@" .. c.host .. ":" .. c.port .. "/" .. c.database
end

return Db
end

-- src/core/psql.lua ---------------------------------------------------------
__modules["core.psql"] = function()
local sys = require("ttt.system")
local U = require("core.util")
local S = require("core.state")

-- psql runs unaligned with the ASCII unit and record separators between
-- fields and rows, and a control character for NULL, so values with commas,
-- quotes, tabs or newlines need no unquoting. The footer stays on: a result
-- set always ends in "<RS>(N rows)\n", which tells it apart from a command
-- tag such as "UPDATE 3".
local M = {}

M.US = "\31"
M.RS = "\30"
M.NULL = "\29"

local function quote(v)
  local s = tostring(v):gsub("\\", "\\\\"):gsub("'", "\\'")
  return "'" .. s .. "'"
end

local function add(parts, key, value)
  value = U.trim(value)
  if value ~= "" then
    parts[#parts + 1] = key .. "=" .. quote(value)
  end
end

-- Every value is quoted, so no argument holds "=!", which ttt refuses.
function M.conninfo(conn)
  local uri = U.trim(conn.uri)
  if uri ~= "" then
    return uri
  end
  local parts = {}
  add(parts, "host", conn.host)
  add(parts, "port", conn.port)
  add(parts, "dbname", conn.database)
  add(parts, "user", conn.user)
  if conn.password and conn.password ~= "" then
    parts[#parts + 1] = "password=" .. quote(conn.password)
  end
  add(parts, "connect_timeout", "10")
  add(parts, "application_name", "ttt-postgres")
  return table.concat(parts, " ")
end

function M.args(conn)
  return {
    "-X",
    "-q",
    "-w",
    "-v",
    "ON_ERROR_STOP=1",
    "-A",
    "-F",
    M.US,
    "-R",
    M.RS,
    "-P",
    "footer=on",
    "-P",
    "null=" .. M.NULL,
    "-d",
    M.conninfo(conn),
  }
end

local function clean_error(text)
  local out = {}
  for _, line in ipairs(U.lines(text)) do
    line = line:gsub("^psql:[^:]*:%d+: ", "")
    line = line:gsub("^psql: error: ", "")
    out[#out + 1] = line
  end
  return table.concat(out, "\n")
end

function M.error_text(res)
  local stderr = U.trim(res.stderr)
  if res.exit_code == -1 then
    if stderr:find("not found", 1, true) or stderr:find("no such file", 1, true) then
      return "psql was not found ("
        .. S.psql_path
        .. "). Install the PostgreSQL client or set its path in Postgres: Settings…"
    end
    return stderr ~= "" and stderr or "psql could not be started"
  end
  if stderr == "" then
    return "psql exited with code " .. tostring(res.exit_code)
  end
  return clean_error(stderr)
end

local function records(body)
  local rows = {}
  for i, record in ipairs(U.split(body, M.RS)) do
    rows[i] = U.split(record, M.US)
  end
  return rows
end

local function timing(line)
  local ms = line:match("^[^:]+: ([%d%.,]+) ms")
  if ms then
    return tonumber((ms:gsub(",", ".")))
  end
end

local function statement(list, cur)
  if not cur then
    cur = {}
    list[#list + 1] = cur
  end
  return cur
end

-- Splits psql's output into statements: { result = { columns, rows }, tag, ms }.
function M.parse(out)
  local list, cur = {}, nil
  local pos, n = 1, #out
  while pos <= n do
    local nl = out:find("\n", pos, true) or (n + 1)
    local line = out:sub(pos, nl - 1)
    local fs = line:find(M.RS, 1, true) and out:find(M.RS .. "%(%d+[^%)\n]*%)\n", pos)
    if fs then
      local rows = records(out:sub(pos, fs - 1))
      local columns = table.remove(rows, 1) or {}
      cur = statement(list, cur)
      if cur.result then
        cur = statement(list, nil)
      end
      cur.result = { columns = columns, rows = rows }
      local _, fe = out:find("%)\n", fs)
      pos = fe + 1
    else
      local ms = timing(line)
      if ms then
        statement(list, cur).ms = ms
        cur = nil
      elseif line ~= "" then
        cur = statement(list, cur)
        cur.tag = line
      end
      pos = nl + 1
    end
  end
  return list
end

local function finished(cb, res)
  local out = { stdout = res.stdout or "", stderr = res.stderr or "", code = res.exit_code }
  if res.exit_code ~= 0 then
    out.err = M.error_text(res)
  end
  out.statements = M.parse(out.stdout)
  cb(out)
end

-- Runs a script on psql's standard input, so neither the SQL nor its length
-- reaches the command line.
function M.run(script, cb)
  if not sys.exec_async then
    return cb({ err = "The plugin needs the system.exec permission for psql.", statements = {} })
  end
  local _, err = sys.exec_async(S.psql_path, M.args(S.conn), { stdin = script }, U.bind(finished, cb))
  if err then
    local msg = tostring(err)
    if msg:find("permission denied", 1, true) then
      msg = msg .. ". Add it to system.exec in plugin.ttt.json and approve the plugin again."
    end
    cb({ err = msg, statements = {} })
  end
end

local function results(cb, out)
  if out.err then
    return cb(out.err)
  end
  local list = {}
  for _, st in ipairs(out.statements) do
    if st.result then
      list[#list + 1] = st.result
    end
  end
  cb(nil, list)
end

-- For the plugin's own catalog queries: cb(err, result_sets).
function M.query(sql, cb)
  M.run(sql, U.bind(results, cb))
end

function M.is_null(v)
  return v == M.NULL
end

return M
end

-- src/core/sql.lua ----------------------------------------------------------
__modules["core.sql"] = function()
local U = require("core.util")

local M = {}

M.CONNECT = [[
select current_user, current_database(), coalesce(host(inet_server_addr()), 'local socket'),
  coalesce(inet_server_port()::text, ''), current_setting('server_version');
select nspname from pg_namespace
where nspname !~ '^pg_' and nspname <> 'information_schema'
order by nspname;
]]

function M.relations(schema)
  return [[
select c.relname, c.relkind, c.reltuples::bigint
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname = ]] .. U.literal(schema) .. [[ and c.relkind in ('r', 'p', 'v', 'm', 'f')
order by c.relname;
]]
end

local function regclass(schema, name)
  return U.literal(U.qualified(schema, name)) .. "::regclass"
end

-- psql's \gset keeps the primary key order in a variable, so the page query
-- pages in a stable order without a second round trip.
function M.page(schema, name, limit, offset)
  local target = U.qualified(schema, name)
  local order = [[
select coalesce('order by ' || string_agg(quote_ident(a.attname), ', ' order by k.n), '') as order_clause
from pg_index i
cross join lateral unnest(i.indkey) with ordinality as k(attnum, n)
join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
where i.indrelid = ]] .. regclass(schema, name) .. " and i.indisprimary \\gset\n"
  local count = string.format("select count(*) from %s;\n", target)
  local rows = string.format("select * from %s :order_clause limit %d offset %d;\n", target, limit, offset)
  return order .. count .. rows
end

function M.structure(schema, name)
  local rel = regclass(schema, name)
  return [[
select c.relkind, pg_size_pretty(pg_total_relation_size(c.oid)), c.reltuples::bigint,
  coalesce(obj_description(c.oid, 'pg_class'), ''),
  case when c.relkind in ('v', 'm') then pg_get_viewdef(c.oid, true) else '' end
from pg_class c where c.oid = ]] .. rel .. [[;
select a.attname, format_type(a.atttypid, a.atttypmod),
  case when a.attnotnull then 'not null' else 'null' end,
  case
    when a.attidentity = 'a' then 'generated always as identity'
    when a.attidentity = 'd' then 'generated by default as identity'
    when a.attgenerated = 's' then 'generated always as (' || pg_get_expr(d.adbin, d.adrelid) || ') stored'
    else coalesce(pg_get_expr(d.adbin, d.adrelid), '')
  end,
  concat_ws(', ',
    case when exists (select 1 from pg_constraint p where p.conrelid = a.attrelid and p.contype = 'p'
      and a.attnum = any(p.conkey)) then 'PK' end,
    case when exists (select 1 from pg_constraint f where f.conrelid = a.attrelid and f.contype = 'f'
      and a.attnum = any(f.conkey)) then 'FK' end),
  coalesce(col_description(a.attrelid, a.attnum), '')
from pg_attribute a
left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
where a.attrelid = ]] .. rel .. [[ and a.attnum > 0 and not a.attisdropped
order by a.attnum;
select c.conname, c.contype, pg_get_constraintdef(c.oid, true)
from pg_constraint c where c.conrelid = ]] .. rel .. [[ order by
  case c.contype when 'p' then 0 when 'f' then 1 when 'u' then 2 else 3 end, c.conname;
select ic.relname, pg_get_indexdef(i.indexrelid),
  case when i.indisprimary then 'primary' when i.indisunique then 'unique' else '' end,
  pg_size_pretty(pg_relation_size(i.indexrelid))
from pg_index i join pg_class ic on ic.oid = i.indexrelid
where i.indrelid = ]] .. rel .. [[ order by i.indisprimary desc, ic.relname;
select c.conrelid::regclass::text, c.conname, pg_get_constraintdef(c.oid, true)
from pg_constraint c where c.confrelid = ]] .. rel .. [[ and c.contype = 'f'
order by 1, 2;
]]
end

function M.query(text)
  return "\\timing on\n\\set QUIET off\n" .. text .. "\n"
end

return M
end

