__modules["features.query.page"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Store = require("features.query.store")

local M = {}

local function set_sql(q, text)
  q.sql = text
end

local function status_text(q)
  if q.running then
    return "Running…", "muted"
  end
  if q.err and q.ran then
    return "✕ Failed · " .. q.summary, "danger"
  end
  if q.ran then
    return "✓ " .. q.summary, "success"
  end
  return "F5 runs the SQL above. Enter on a result row shows it in full.", "muted"
end

local function toolbar(q, h)
  h:button({ label = "Run", disabled = q.running, on_click = U.bind(Store.run, q) })
  local text, style = status_text(q)
  h:label({ text = text, style = style })
end

local function results(q, p)
  if q.err then
    UI.error_box(p, "Error", q.err)
  end
  if q.notices then
    UI.error_box(p, "Notices", q.notices)
  end
  if q.result and #q.result.columns > 0 then
    UI.grid.render(p, q.grid, { title = q.title, empty = "The query returned no rows" })
  end
end

local function render(q, p)
  S.active_query = q
  p:input({
    border = true,
    title = "SQL",
    value = q.sql,
    placeholder = "select * from …",
    multiline = true,
    min_rows = 8,
    max_rows = 8,
    autofocus = true,
    margin_top = 1,
    on_change = U.bind(set_sql, q),
  })
  UI.toolbar(p, U.bind(toolbar, q), 0)
  results(q, p)
end

local function on_event(q, ev)
  if ev.type == "key" and ev.key == "F5" then
    Store.run(q)
    return true
  end
end

local function forget(q)
  if S.active_query == q then
    S.active_query = nil
  end
end

function M.page(q)
  return {
    title = q.title,
    render = U.bind(render, q),
    on_event = U.bind(on_event, q),
    on_close = U.bind(forget, q),
  }
end

return M
end

-- src/features/query/store.lua ----------------------------------------------
__modules["features.query.store"] = function()
local U = require("core.util")
local S = require("core.state")
local Psql = require("core.psql")
local SQL = require("core.sql")
local UI = require("components")

local M = {}

M.count = 0

function M.new(sql)
  M.count = M.count + 1
  return {
    id = M.count,
    title = "Query " .. M.count,
    sql = sql or "",
    running = false,
    ran = false,
    err = nil,
    notices = nil,
    summary = "",
    result = nil,
    gen = 0,
    grid = UI.grid.new(),
  }
end

local function summarize(q, statements)
  local ms, tags, result, count = 0, {}, nil, 0
  for _, st in ipairs(statements) do
    count = count + 1
    ms = ms + (st.ms or 0)
    if st.result then
      result = st.result
    end
    if st.tag then
      tags[#tags + 1] = st.tag
    end
  end
  local parts = {}
  if count > 1 then
    parts[#parts + 1] = U.plural(count, "statement")
  end
  if result then
    parts[#parts + 1] = U.plural(#result.rows, "row")
  end
  for _, tag in ipairs(tags) do
    parts[#parts + 1] = tag
  end
  parts[#parts + 1] = string.format("%.1f ms", ms)
  return table.concat(parts, " · "), result
end

local function finished(q, gen, out)
  if gen ~= q.gen then
    return
  end
  q.running = false
  q.ran = true
  q.err = out.err
  q.notices = nil
  if not out.err and U.trim(out.stderr) ~= "" then
    q.notices = U.trim(out.stderr)
  end
  local summary, result = summarize(q, out.statements or {})
  q.summary = summary
  q.result = result
  UI.grid.set_result(q.grid, result)
  S.redraw()
end

function M.run(q)
  if q.running then
    return
  end
  if U.trim(q.sql) == "" then
    q.err = "Type a query first."
    S.redraw()
    return
  end
  q.gen = q.gen + 1
  q.running = true
  q.err = nil
  S.redraw()
  Psql.run(SQL.query(q.sql), U.bind(finished, q, q.gen))
end

return M
end

-- src/features/table/init.lua -----------------------------------------------
__modules["features.table"] = function()
local U = require("core.util")
local Router = require("app.router")
local Store = require("features.table.store")
local Page = require("features.table.page")

local M = {}

M.store = Store
M.page = Page

-- Opens a table or view in its own tab, or focuses it when it is open.
function M.open(schema, name, kind)
  local rel = Store.relation(schema, name, kind)
  Router.show("table:" .. rel.key, U.bind(Page.page, rel))
end

return M
end

-- src/features/table/page.lua -----------------------------------------------
__modules["features.table.page"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Router = require("app.router")
local Store = require("features.table.store")
local Structure = require("features.table.structure_tab")

local M = {}

local TABS = { { id = "data", label = "Data" }, { id = "structure", label = "Structure" } }

M.open_query = nil

local function data_tab(p, rel)
  local grid = rel.data
  if not grid.loaded and not grid.loading then
    Store.load_data(rel, 0)
  end
  if grid.err then
    UI.error_box(p, "Couldn't load rows", grid.err)
    return
  end
  UI.grid.render(p, grid, { title = rel.key, empty = "No rows in " .. rel.name })
  UI.status(p, "Enter shows the whole row.")
end

local function refresh(page, rel)
  if page.tab == "structure" then
    Store.load_structure(rel)
  else
    Store.load_data(rel)
  end
end

local function query(rel)
  if M.open_query then
    M.open_query("select *\nfrom " .. U.qualified(rel.schema, rel.name) .. "\nlimit 100;")
  end
end

local function actions(page, rel, h)
  h:button({ label = "Refresh", on_click = U.bind(refresh, page, rel) })
  h:button({ label = "Query", on_click = U.bind(query, rel) })
end

local function render(page, rel, p)
  S.active_query = nil
  local current = Router.tab_strip(p, page, TABS)
  if current == "structure" then
    Structure.render(p, rel)
  else
    data_tab(p, rel)
  end
end

function M.page(rel)
  local page = { title = rel.key, tab_title = rel.name, on_close = U.bind(Store.forget, rel.key) }
  page.actions = U.bind(actions, page, rel)
  page.render = U.bind(render, page, rel)
  return page
end

return M
end

-- src/features/table/store.lua ----------------------------------------------
__modules["features.table.store"] = function()
local U = require("core.util")
local S = require("core.state")
local Psql = require("core.psql")
local SQL = require("core.sql")
local UI = require("components")

local M = {}

M.relations = {}

function M.key(schema, name)
  return schema .. "." .. name
end

local function data_loaded(rel, gen, err, sets)
  local grid = rel.data
  if gen ~= grid.gen then
    return
  end
  grid.loading = false
  grid.loaded = true
  grid.err = err
  if err then
    grid.rows = {}
  else
    local count, page = sets[1], sets[2]
    grid.total = tonumber(count and count.rows[1] and count.rows[1][1]) or 0
    grid.columns = page and page.columns or {}
    grid.rows = page and page.rows or {}
    if grid.sel > #grid.rows then
      grid.sel = math.max(#grid.rows, 1)
    end
  end
  S.redraw()
end

function M.load_data(rel, offset)
  local grid = rel.data
  grid.offset = offset or grid.offset
  grid.gen = grid.gen + 1
  grid.loading = true
  S.redraw()
  Psql.query(SQL.page(rel.schema, rel.name, S.page_size, grid.offset), U.bind(data_loaded, rel, grid.gen))
end

local function rows_of(set)
  return set and set.rows or {}
end

local function structure_loaded(rel, gen, err, sets)
  local st = rel.structure
  if gen ~= st.gen then
    return
  end
  st.loading = false
  st.loaded = true
  st.err = err
  if not err then
    local info = rows_of(sets[1])[1] or {}
    st.info = { relkind = info[1], size = info[2], estimate = tonumber(info[3]), comment = info[4], viewdef = info[5] }
    st.columns = rows_of(sets[2])
    st.constraints = rows_of(sets[3])
    st.indexes = rows_of(sets[4])
    st.referenced_by = rows_of(sets[5])
  end
  S.redraw()
end

function M.load_structure(rel)
  local st = rel.structure
  st.gen = st.gen + 1
  st.loading = true
  S.redraw()
  Psql.query(SQL.structure(rel.schema, rel.name), U.bind(structure_loaded, rel, st.gen))
end

function M.relation(schema, name, kind)
  local key = M.key(schema, name)
  local rel = M.relations[key]
  if not rel then
    rel = {
      key = key,
      schema = schema,
      name = name,
      kind = kind or "table",
      data = UI.grid.new({ gen = 0 }),
      structure = { gen = 0, loaded = false, loading = false },
    }
    rel.data.on_page = U.bind(M.load_data, rel)
    M.relations[key] = rel
  end
  return rel
end

function M.forget(key)
  M.relations[key] = nil
end

function M.reload_all()
  for _, rel in pairs(M.relations) do
    rel.data.offset = 0
    rel.data.loaded = false
    rel.structure.loaded = false
  end
end

return M
end

-- src/features/table/structure_tab.lua --------------------------------------
__modules["features.table.structure_tab"] = function()
local U = require("core.util")
local UI = require("components")
local Store = require("features.table.store")

local M = {}

local KIND = { r = "Table", p = "Partitioned table", f = "Foreign table", v = "View", m = "Materialized view" }
local CONTYPE = { p = "primary key", f = "foreign key", u = "unique", c = "check", x = "exclusion", t = "trigger" }

local COLUMN_COLUMNS = {
  { label = "#", width = 3, align = "right" },
  { label = "Name" },
  { label = "Type" },
  { label = "Null", width = 8 },
  { label = "Default" },
  { label = "Key", width = 6 },
}

local INDEX_COLUMNS = {
  { label = "Name" },
  { label = "Kind", width = 8 },
  { label = "Size", width = 10, align = "right" },
  { label = "Definition" },
}

local FK_COLUMNS = { { label = "Name" }, { label = "Definition" } }
local REF_COLUMNS = { { label = "Table" }, { label = "Name" }, { label = "Definition" } }
local CONSTRAINT_COLUMNS = { { label = "Name" }, { label = "Type", width = 10 }, { label = "Definition" } }

local function section_table(columns, rows, empty, b)
  b:table({ inset = 1, columns = UI.grid.fit(columns, rows), rows = rows, empty = empty })
end

local function section(p, title, columns, rows, empty)
  UI.frame(
    p,
    title .. "  " .. tostring(#rows),
    U.bind(section_table, columns, rows, empty),
    { height = math.max(#rows, 1) + 5, margin_top = 1 }
  )
end

local function definition_lines(lines, b)
  for _, line in ipairs(lines) do
    b:label({ text = line, style = "code", padding_left = 1 })
  end
end

local function view_definition(p, text)
  local lines = U.split(U.trim(text), "\n")
  UI.frame(p, "Definition", U.bind(definition_lines, lines), { height = #lines + 3, margin_top = 1 })
end

local function split_constraints(st)
  local pk, fks, others = nil, {}, {}
  for _, c in ipairs(st.constraints or {}) do
    if c[2] == "p" then
      pk = c[3]
    elseif c[2] == "f" then
      fks[#fks + 1] = { c[1], c[3] }
    else
      others[#others + 1] = { c[1], CONTYPE[c[2]] or c[2], c[3] }
    end
  end
  return pk, fks, others
end

local function column_rows(st)
  local rows = {}
  for i, c in ipairs(st.columns or {}) do
    rows[i] = { tostring(i), c[1], c[2], c[3], UI.grid.cell(c[4]), c[5] }
  end
  return rows
end

local function index_rows(st)
  local rows = {}
  for i, ix in ipairs(st.indexes or {}) do
    rows[i] = { ix[1], ix[3], ix[4], ix[2] }
  end
  return rows
end

local function ref_rows(st)
  local rows = {}
  for i, r in ipairs(st.referenced_by or {}) do
    rows[i] = { r[1], r[2], r[3] }
  end
  return rows
end

local function body(rel, sv)
  local st = rel.structure
  local info = st.info or {}
  local pk, fks, others = split_constraints(st)
  local is_view = info.relkind == "v" or info.relkind == "m"
  local estimate = info.estimate and info.estimate >= 0 and U.count(info.estimate) or "not analyzed"
  local kv = { { "Kind", KIND[info.relkind] or info.relkind } }
  if info.relkind ~= "v" then
    kv[#kv + 1] = { "Estimated rows", estimate }
    kv[#kv + 1] = { "Total size", info.size }
  end
  if not is_view then
    kv[#kv + 1] = { "Primary key", pk or "none" }
  end
  if info.comment and info.comment ~= "" then
    kv[#kv + 1] = { "Comment", info.comment }
  end
  sv:keyvalue(UI.kv(kv))
  section(sv, "Columns", COLUMN_COLUMNS, column_rows(st), "No columns")
  if is_view and info.viewdef ~= "" then
    view_definition(sv, info.viewdef)
  end
  if info.relkind ~= "v" then
    section(sv, "Indexes", INDEX_COLUMNS, index_rows(st), "No indexes")
  end
  if not is_view then
    section(sv, "Foreign keys", FK_COLUMNS, fks, "No foreign keys")
    section(sv, "Referenced by", REF_COLUMNS, ref_rows(st), "No foreign keys point here")
    section(sv, "Other constraints", CONSTRAINT_COLUMNS, others, "No unique, check or exclusion constraints")
  end
end

function M.render(p, rel)
  local st = rel.structure
  if not st.loaded and not st.loading then
    Store.load_structure(rel)
  end
  if st.err then
    UI.error_box(p, "Couldn't load the structure", st.err)
    return
  end
  if not st.loaded then
    UI.status(p, "Loading…")
    return
  end
  p:scrollview({ render = U.bind(body, rel) })
end

return M
end

-- src/main.lua --------------------------------------------------------------
__modules["main"] = function()
local ttt = require("ttt")
local S = require("core.state")
local Db = require("core.db")
local Sidebar = require("app.sidebar")
local Connection = require("app.connection")
local Settings = require("app.settings")
local Table = require("features.table")
local Query = require("features.query")

Sidebar.open_relation = Table.open
Sidebar.new_query = Query.new
Table.page.open_query = Query.open_with

local function settings_changed()
  Table.store.reload_all()
  S.redraw()
end

Settings.on_change = settings_changed

local function new_query()
  Query.new()
end

local function refresh()
  Db.refresh()
  Table.store.reload_all()
  S.redraw()
end

local sidebar_actions = {
  connection = Connection.dialog,
  settings = Settings.dialog,
  query = new_query,
  reconnect = Db.connect,
  refresh = refresh,
}

local function on_action(cmd)
  local run = sidebar_actions[cmd]
  if run then
    run()
  end
end

ttt.register({
  sidebar = {
    title = "Postgres",
    render = Sidebar.render,
    actions = {
      { label = "New Query", command = "query" },
      { label = "Refresh", command = "refresh" },
      { separator = true },
      { label = "Connection…", command = "connection" },
      { label = "Settings…", command = "settings" },
      { label = "Reconnect", command = "reconnect" },
    },
    on_action = on_action,
  },
  commands = {
    { id = "postgres.connect", title = "Postgres: Connect…", handler = Connection.dialog },
    { id = "postgres.newQuery", title = "Postgres: New Query", handler = new_query },
    { id = "postgres.runQuery", title = "Postgres: Run Query", handler = Query.run_active },
    { id = "postgres.refresh", title = "Postgres: Refresh", handler = refresh },
    { id = "postgres.reconnect", title = "Postgres: Reconnect", handler = Db.connect },
    { id = "postgres.settings", title = "Postgres: Settings…", handler = Settings.dialog },
  },
})
end

require("main")
